  // The rotating hero. Every slide opens a set that exists and states its
  // size, so the number on the card is checkable by tapping it.
  // ── Seasons as a dated block ──────────────────────────────────────────
  // Two cards, not four tiles: the season running and the one after it. A
  // season is a commitment with an end date, and the countdown is the point.
